From af91d7512ffdac3a00883f5348ef02b025998e14 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:28:37 +0100
Subject: [PATCH] applet: keep expansion on the same connection when the list
 re-sorts

Expansion lived in the list delegate, so when a connection moved after
being disconnected or connected, the one taking its row was shown
expanded. Remember expanded connections and restore them per delegate.

BUG: 469999
---
 applet/ConnectionItem.qml     | 24 ++++++++++++++++++++++++
 applet/ConnectionListPage.qml |  3 +++
 2 files changed, 27 insertions(+)

diff --git a/applet/ConnectionItem.qml b/applet/ConnectionItem.qml
index e2a79fd2f..877a0da9c 100644
--- a/applet/ConnectionItem.qml
+++ b/applet/ConnectionItem.qml
@@ -36,6 +36,8 @@ PlasmaExtras.ExpandableListItem {
     property bool predictableWirelessPassword: !model.Uuid && model.Type === PlasmaNM.Enums.Wireless && passwordIsStatic
     property bool showSpeed: mainWindow.expanded && model.ConnectionState === PlasmaNM.Enums.Activated

+    readonly property string connectionKey: model.ConnectionPath || model.Ssid
+
     property real rxSpeed: 0
     property real txSpeed: 0

@@ -335,12 +337,34 @@ PlasmaExtras.ExpandableListItem {
         }
     }

+    onConnectionKeyChanged: {
+        if (!connectionKey) {
+            return;
+        }
+        const shouldBeExpanded = !!listView.expandedConnections[connectionKey];
+        if (shouldBeExpanded && !expanded) {
+            expand();
+        } else if (!shouldBeExpanded && expanded) {
+            collapse();
+        }
+    }
+
+    onItemExpanded: {
+        if (connectionKey) {
+            listView.expandedConnections[connectionKey] = true;
+        }
+    }
+
     onItemCollapsed: {
+        delete listView.expandedConnections[connectionKey];
         connectionItem.customExpandedViewContent = detailsComponent;
         setDelayModelUpdates(false);
     }

     Component.onDestruction: {
+        if (expanded) {
+            delete listView.expandedConnections[connectionKey];
+        }
         showSpeed = false;
         setDelayModelUpdates(false);
     }
diff --git a/applet/ConnectionListPage.qml b/applet/ConnectionListPage.qml
index b3b8d917e..3abdd81b1 100644
--- a/applet/ConnectionListPage.qml
+++ b/applet/ConnectionListPage.qml
@@ -59,6 +59,9 @@ ColumnLayout {
             id: connectionView

             property int currentVisibleButtonIndex: -1
+            // Keys of the expanded connections, so that expansion follows the
+            // connection rather than the row when the model is re-sorted
+            property var expandedConnections: ({})

             Keys.onDownPressed: event => {
                 connectionView.incrementCurrentIndex();
-- 
